"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8094],{88094:a=>{a.exports=JSON.parse('{"slug":"inflyaciya-uskorilas-ohlazhdenie-ekonomiki","locale":"zh","title":"俄罗斯周通胀连续第二周加速，居民预期升至14.2%","description":"周通胀三周内由0.02%升至0.12%，居民预期14.2%。解释其对央行十月23日利率决定的意义。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年九月22–28日俄罗斯物价涨0.12%，此前一周0.06%，再前一周0.02%，为七月末以来最快。若每周0.12%持续，全年约6.4%（1.0012的52次方），而央行目标4%。单周说明有限，连续三周加速已值得注意。"},{"id":"b002","kind":"paragraph","text":"秋季蔬菜降价拉低通胀，但力度减弱：九月最后一周土豆跌3.2%，前周3.4%。同时鸡蛋涨1.9%，荞麦与小米0.8%。截至九月28日年通胀约6.25%，年初以来涨4.93%，高于2025年同期4.29%。"},{"id":"b003","kind":"paragraph","text":"央行九月估计八月剔除偶然跳涨后的持续通胀，折年5–6%。夏季上涨主要因燃料：七月季调折年11.7%，八月6.9%。冲击过去，但未回4%目标，关键利率仍14%。"},{"id":"b004","kind":"paragraph","text":"高利率让经济降温：贷款贵，居民和企业减少支出，涨价变慢。但人们相信会放缓时政策更有效。九月居民预期未来一年涨14.2%，八月13.7%，实际同比约6.25%。若预期物价涨14%，14%利率几乎没有实际成本，立即买似乎比存钱划算。这就是通胀预期；央行警告高预期会阻碍降温。"},{"id":"b005","kind":"paragraph","text":"尚不清楚是新加速起点还是偶然波动。Rosstat十月9日发九月月度数据，央行十月23日决定利率。对普通人，九月末10大银行平均最高存款利率13.05%，仍高于约6.25%通胀。押注很快降息借贷有风险，永远等待也有代价，因为价格一直涨。"},{"id":"b006","kind":"heading","text":"俄罗斯2026年九月末通胀是多少？"},{"id":"b007","kind":"paragraph","text":"截至九月28日同比约6.25%，年初以来4.93%。九月最后一周0.12%，为七月末以来最快。Rosstat十月9日公布正式月度数据。"},{"id":"b008","kind":"heading","text":"2026年九月通胀为何加速？"},{"id":"b009","kind":"paragraph","text":"蔬菜季节性降价，但慢于前周；鸡蛋和谷物上涨，鸡蛋最后一周涨1.9%。央行估计持续通胀折年5–6%，高于4%目标。"},{"id":"b010","kind":"heading","text":"通胀预期是什么，为何影响利率？"},{"id":"b011","kind":"paragraph","text":"这是居民预计未来一年涨幅，2026年九月为14.2%。预期如此高时，14%利率几乎没有实际成本，人们不推迟购买，所以高预期阻碍央行降息。"}],"sources":[{"label":"最近一周通胀0.12%","url":"https://www.vedomosti.ru/economics/news/2026/09/30/1233212-nedelnaya-inflyatsiya"},{"label":"俄罗斯周通胀加速至0.06%","url":"https://www.vedomosti.ru/economics/news/2026/09/23/1231274-inflyatsiya-rossii-uskorilas"},{"label":"九月22日至28日周通胀0.12%，同比放缓至6.25%","url":"https://www.interfax.ru/business/1119451"},{"label":"俄罗斯居民九月通胀预期升至14.2%","url":"https://www.vedomosti.ru/economics/news/2026/09/22/1230887-inflyatsionnie-ozhidaniya"},{"label":"央行估计八月持续通胀为5–6%","url":"https://ru.themoscowtimes.com/2026/09/16/tsbr-otsenil-ustoychivuyu-inflyatsiyu-v-avguste-v-diapazone-5-6-a206280"},{"label":"十大银行平均最高存款利率升至13.05%","url":"https://ria.ru/20261001/bank-2121443529.html"},{"label":"俄罗斯央行维持关键利率14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"a98c31881322940d45b158db2ab6716a039490f89eea6f0ffe309fb1f7594ee1"}')}}]);